select case when year(p.launch_date) < 2024 then 'before_2024' when year(p.launch_date) = 2024 then '2024' else 'after_2024' end as launch_cohort, round(avg(i.quantity), 2) as avg_quantity, count(*) as inventory_count from inventory i inner join products p on i.product_id = p.id group by case when year(p.launch_date) < 2024 then 'before_2024' when year(p.launch_date) = 2024 then '2024' else 'after_2024' end
